// fp256 is the same code as fp128 on 256 bits: generate it so that both stay in sync.
// Run `node scripts/generate-fp256.mjs` after editing assembly/fixed/fp128.ts or
// assembly/fixed/safe/fp128.ts (`--check` fails if the generated files are outdated).

import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const check = process.argv.includes("--check");

const HEADER =
  "// Generated by scripts/generate-fp256.mjs from the fp128 version: do not edit.\n\n";

const used = new Set();

const REPLACEMENTS = [
  // specific cases first
  ["@lazy const N = 4;", "@lazy const N = 8;"],
  ["@lazy const BITS = 128;", "@lazy const BITS = 256;"],
  ["value.hi >>> 63", "value.hi2 >>> 63"],
  ["// 2^127", "// 2^255"],
  ["between 1 and 126", "between 1 and 254"],
  ["`fp128<u64>` is a Q63.64 number", "`fp256<u64>` is a Q191.64 number"],
  ["on 128 bits", "on 256 bits"],
  // types
  [/fp128/g, "fp256"],
  [/i128/g, "i256"],
  [/u128/g, "u256"],
  [/I128/g, "I256"], // fromI128, toI128
  [/U128/g, "U256"], // fromU128
];

function generate(source) {
  let out = source;
  for (const [from, to] of REPLACEMENTS) {
    if (typeof from == "string") {
      if (out.includes(from)) used.add(from);
      out = out.replaceAll(from, to);
    } else {
      out = out.replace(from, to);
    }
  }
  return HEADER + out;
}

let outdated = false;
for (const [src, dst] of [
  ["assembly/fixed/fp128.ts", "assembly/fixed/fp256.ts"],
  ["assembly/fixed/safe/fp128.ts", "assembly/fixed/safe/fp256.ts"],
]) {
  const generated = generate(readFileSync(join(root, src), "utf8"));
  const path = join(root, dst);
  let current = "";
  try { current = readFileSync(path, "utf8"); } catch {}
  if (current == generated) continue;
  if (check) {
    console.error(`${dst} is outdated: run node scripts/generate-fp256.mjs`);
    outdated = true;
  } else {
    writeFileSync(path, generated);
    console.log(`wrote ${dst}`);
  }
}
// every replacement must still apply to one of the sources
const stale = REPLACEMENTS
  .map(([from]) => from)
  .filter((from) => typeof from == "string" && !used.has(from));
if (stale.length) {
  console.error(`patterns not found, update the generator: ${stale.join(", ")}`);
  outdated = true;
}
process.exit(outdated ? 1 : 0);
